async function viewChores(e,t="daily"){const o="todo"===t,[a,n,i]=await Promise.all([api("/chores"),api("/todos"),api("/family/members")]),l=e=>"all"===CHORE_WHO||String(e.user_id??"")===String(CHORE_WHO),r=a.filter(l),d=o?n.filter(l):r.filter(e=>e.cadence===t),s=d.filter(e=>e.done).length,c=d.length?Math.round(s/d.length*100):0,h=((new Date).getDay()+6)%7,y=r.filter(e=>!e.done&&("daily"===e.cadence||null==e.weekday||Number(e.weekday)===h)).length;e.innerHTML=`<div class="pagehead"><div><h1>Chores</h1><p>${tr(o?"One-off jobs. Ticking one is the end of it — nothing comes back tomorrow.":"Recurring jobs around the house. Ticking one marks it done for today — it comes back tomorrow.")}</p></div></div>\n    <section class="card chorehead">\n      <div class="row" style="justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap">\n        <div><div class="muted" style="font-size:12px">${tr(o?"Still to do":"Left for today")}</div>\n          <div class="chorecount">${o?d.length-s:y}</div></div>\n        <div style="text-align:right"><div class="muted" style="font-size:12px">${tr(o?"Ticked off":"weekly"===t?"Done this week":"Done today")}</div>\n          <div class="amount"><b>${s}/${d.length}</b></div></div>\n      </div>\n      <div class="scorebar" style="margin-top:12px"><i style="width:${c}%"></i></div>\n    </section>\n\n    <div class="tabs" style="max-width:520px">\n      ${[["daily","Daily"],["weekly","Weekly"],["todo","To-do"]].map(([e,o])=>`<button data-t="${e}" class="${e===t?"active":""}">${tr(o)}</button>`).join("")}\n    </div>\n    <div class="card">\n      <div class="row filterrow" style="margin-top:0">\n        <select id="chorewho">\n          <option value="all" ${"all"===CHORE_WHO?"selected":""}>${tr("Everyone")}</option>\n          <option value="" ${""===CHORE_WHO?"selected":""}>${tr("Nobody in particular")}</option>\n          ${i.map(e=>`<option value="${e.id}" ${String(CHORE_WHO)===String(e.id)?"selected":""}>${esc(e.name)}</option>`).join("")}\n        </select>\n      </div>\n      ${d.length?`<ul class="chorelist">${d.map(e=>`<li class="chorerow${e.done?" is-done":""}">\n        <label class="chorecheck">\n          <input type="checkbox" data-${o?"todo":"chore"}="${e.id}" ${e.done?"checked":""} ${canWrite()?"":"disabled"} style="width:auto">\n          <span class="chorebody">\n            <span class="choretitle">${esc(e.title)}</span>\n            <span class="muted choremeta">${(o?[e.user_name?esc(e.user_name):tr("anyone"),e.due_date?`${tr("by")} ${fdate(e.due_date)}`:tr("no deadline"),e.done&&e.done_by_name?`${tr("done by")} ${esc(e.done_by_name)}`:"",e.note?esc(e.note):""]:[e.user_name?esc(e.user_name):tr("anyone"),"weekly"===e.cadence?null==e.weekday?tr("any day this week"):tr(WEEKDAYS[e.weekday]):"",e.done&&e.done_by_name?`${tr("done by")} ${esc(e.done_by_name)}`:"",e.note?esc(e.note):""]).filter(Boolean).join(" · ")}</span>\n          </span>\n        </label>\n        ${canWrite()?`<button class="btn danger small iconbtn" data-${o?"tddel":"chdel"}="${e.id}" aria-label="${tr("Delete")}" data-tip="${tr("Delete")}">✕</button>`:""}\n      </li>`).join("")}</ul>`:`<div class="empty"><b>${tr(o?"Nothing on the list":"Nothing here yet")}</b>${tr(o?"Add a one-off job below — it stays put until someone ticks it.":"Add a chore below and it will show up every day.")}</div>`}\n\n      ${canWrite()&&o?`<div class="subform">\n        <h4>${tr("New task")}</h4>\n        <form id="todoform" class="formgrid">\n          <div><label>${tr("Task")}</label><input name="title" placeholder="${tr("Change the front door lock")}" required></div>\n          <div><label>${tr("By when")} <span class="muted">${tr("optional")}</span></label><input name="due_date" type="date"></div>\n          <div><label>${tr("Person")}</label><select name="user_id"><option value="">${tr("Anyone")}</option>\n            ${i.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join("")}</select></div>\n          <div><label>${tr("Note")} <span class="muted">${tr("optional")}</span></label><input name="note"></div>\n          <button class="btn small">${tr("Add task")}</button>\n        </form></div>`:""}\n\n      ${canWrite()&&!o?`<div class="subform">\n        <h4>${tr("New chore")}</h4>\n        <form id="choreform" class="formgrid">\n          <div><label>${tr("Chore")}</label><input name="title" placeholder="${tr("Feed the dogs")}" required></div>\n          <div><label>${tr("How often")}</label><select name="cadence" id="chcad">\n            <option value="daily" ${"daily"===t?"selected":""}>${tr("Daily")}</option>\n            <option value="weekly" ${"weekly"===t?"selected":""}>${tr("Weekly")}</option></select></div>\n          <div id="chdaywrap" ${"weekly"===t?"":"hidden"}><label>${tr("Day")}</label><select name="weekday">\n            <option value="">${tr("Any day")}</option>\n            ${WEEKDAYS.map((e,t)=>`<option value="${t}">${tr(e)}</option>`).join("")}</select></div>\n          <div><label>${tr("Person")}</label><select name="user_id"><option value="">${tr("Anyone")}</option>\n            ${i.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join("")}</select></div>\n          <button class="btn small">${tr("Add chore")}</button>\n        </form></div>`:""}\n    </div>`,e.querySelectorAll(".tabs button").forEach(t=>t.onclick=()=>viewChores(e,t.dataset.t)),e.querySelector("#chorewho").onchange=o=>{CHORE_WHO=o.target.value,viewChores(e,t)};const m=e.querySelector("#chcad");m&&(m.onchange=()=>{e.querySelector("#chdaywrap").hidden="weekly"!==m.value}),e.querySelectorAll("[data-chore]").forEach(o=>o.onchange=async()=>{o.closest(".chorerow").classList.toggle("is-done",o.checked);try{await api(`/chores/${o.dataset.chore}/toggle`,{method:"POST"}),viewChores(e,t)}catch(o){toast(o.message,"error"),viewChores(e,t)}}),e.querySelectorAll("[data-todo]").forEach(o=>o.onchange=async()=>{o.closest(".chorerow").classList.toggle("is-done",o.checked);try{await api(`/todos/${o.dataset.todo}/toggle`,{method:"POST"}),viewChores(e,t)}catch(o){toast(o.message,"error"),viewChores(e,t)}}),e.querySelectorAll("[data-chdel]").forEach(o=>o.onclick=()=>{const{hide:a,restore:n}=rowHide(o);undoableDelete({btn:o,what:"chore",hide:a,restore:n,commit:()=>api("/chores/"+o.dataset.chdel,{method:"DELETE"}).then(()=>viewChores(e,t))})}),e.querySelectorAll("[data-tddel]").forEach(o=>o.onclick=()=>{const{hide:a,restore:n}=rowHide(o);undoableDelete({btn:o,what:"todo",hide:a,restore:n,commit:()=>api("/todos/"+o.dataset.tddel,{method:"DELETE"}).then(()=>viewChores(e,t))})}),e.querySelector("#choreform")?.addEventListener("submit",async o=>{o.preventDefault();const a=Object.fromEntries(new FormData(o.target));try{await api("/chores",{method:"POST",body:a}),viewChores(e,a.cadence||t)}catch(e){toast(e.message,"error")}}),e.querySelector("#todoform")?.addEventListener("submit",async t=>{t.preventDefault();try{await api("/todos",{method:"POST",body:Object.fromEntries(new FormData(t.target))}),viewChores(e,"todo")}catch(e){toast(e.message,"error")}})}